import { useState, useEffect } from "react"
import Home from "../defaultresort/home";
import "../defaultresort/roomcarts.css"

const AllRoomsList = () => {

    let [ store, setStore ] = useState([]);

    const getdata = () => {
        try{
            fetch("http://localhost:1234/room")
            .then( res => res.json() )
            .then( info => {
                setStore(info)
            })
        }catch(error){
            console.error(" Data fetching is not processed ")
        }
    }

    useEffect( () => {
        getdata()
    }, [])

    return(
        <>
            <Home />
            <div className="container" >
                <h2 className="fw-bolder ms-md-4" > LIST OF ROOM AVAILABLE </h2>
                    <div className="row pt-5" >

                        {
                            store.map( ( value, index ) => {
                                return(
                                    <div className="col-md-4 mt-4" >
                                        <div className=" card hovers rounded-5" key={index} >
                                            <img src={value.image} alt="images" className=" p-2 rounded-5" />
                                            <div className=" card-body " >
                                                <h3 className="card-title fw-bold"> Room : {value.rooms} </h3>
                                                <div> 1hr/50m <br/> Tue 18/2 to Sat 22/2  </div> 
                                                <h3 className=" fw-bold mt-5" > from : $ 200 </h3>
                                            </div>
                                        </div>
                                    </div>
                                )
                            })
                        }
                    </div>
            </div>       
        </>
    )
}

export default AllRoomsList
